input.old_string:
{#if pdfUrl}
	<div class="search-bar">
		<input
			type="text"
			placeholder="Search in PDF..."
			bind:value={searchQuery}
			bind:this={searchInputEl}
			oninput={performSearch}
			onkeydown={handleSearchKeydown}
			class="search-input"
